`timescale 1ns / 1ps
//////////////////////////////////////////////////////////////////////////////////
// Company: Stone Arch Silicon
// Engineer: Paulo Dietrich
//
// Module Name: arithmetic_tb
// Project Name: Systolic Array IP
//
// Description:
// Checks FP16 dot products and final rounding against exact rational
// vectors generated by tools/reference.py. Inserts clock-enable stalls
// and compares result bits plus exception flags without DUT math reuse.
// Retains the supplied testbench template section structure.
//
// Revision:
// Revision 0.01 - Initial parameterized implementation.
// Revision 0.02 - Readability, section comments, and module documentation.
// Revision 0.03 - Short module names and explicit controller FSMs.
// Additional Comments:
// Configure the IP in rtl/sa_pkg.sv and re-elaborate after edits.
// Port names and cycle timing are retained; module names are shortened.
//////////////////////////////////////////////////////////////////////////////////

module arithmetic_tb;
    import sa_pkg::*;

    // ====
    // DUT
    // ====
    // --------
    // Signals
    // --------
    logic       clk = 0;
    logic       rst_n = 0;
    logic       ce = 1;
    logic       valid = 0;
    operand_t   a = 0;
    operand_t   b = 0;
    operand_t   unused_a;
    operand_t   unused_b;
    logic [1:0] tag = 0;
    logic [1:0] unused_tag;
    logic       unused_av;
    logic       unused_bv;
    logic       last_done;
    logic       result_valid;
    accum_t     sum;
    accum_t     carry;
    special_t   special;
    result_t    result;
    logic [4:0] flags;
    integer     pass_count = 0;
    integer     fail_count = 0;

    // -----------
    // Parameters
    // -----------
    localparam CLK_PERIOD = 10;

    // ------------
    // Start clock
    // ------------
    always #(CLK_PERIOD / 2) clk = ~clk;

    // ----------------
    // Instantiate DUT
    // ----------------
    pe_os DUT (
        .clk             (clk),
        .rst_n           (rst_n),
        .clear           (1'b0),
        .ce              (ce),
        .active          (1'b1),
        .a_i             (a),
        .b_i             (b),
        .av_i            (valid),
        .bv_i            (valid),
        .tag_i           (tag),
        .a_o             (unused_a),
        .b_o             (unused_b),
        .av_o            (unused_av),
        .bv_o            (unused_bv),
        .tag_o           (unused_tag),
        .drain           (1'b0),
        .drain_sum_i     (accum_t'('0)),
        .drain_carry_i   (accum_t'('0)),
        .drain_special_i (special_t'('0)),
        .result_sum_o    (sum),
        .result_carry_o  (carry),
        .result_special_o(special),
        .last_done       (last_done)
    );
    finalize u_round (
        .clk      (clk),
        .rst_n    (rst_n),
        .clear    (1'b0),
        .ce       (ce),
        .valid_i  (last_done),
        .sum_i    (sum),
        .carry_i  (carry),
        .special_i(special),
        .valid_o  (result_valid),
        .data_o   (result),
        .flags_o  (flags)
    );

    // =============
    // Golden Model
    // =============
    // Exact rational vectors are computed outside the RTL by reference.py.
    result_t    expected;
    logic [4:0] expected_flags;

    // ======
    // Tasks
    // ======
    task automatic reset_dut;
        @(negedge clk);
        rst_n = 0;
        valid = 0;
        ce    = 1;
        repeat (3)
            @(negedge clk);
        rst_n = 1;
    endtask

    task automatic check(
        input  integer index
    );
        if (result !== expected || flags !== expected_flags) begin
            $display("FAIL dot=%0d actual=%h/%h expected=%h/%h", index, result, flags, expected,
                     expected_flags);
            fail_count++;
            if (fail_count > 10)
                $fatal(1, "Too many arithmetic failures");
        end else
            pass_count++;
    endtask

    // =============
    // Test timeout
    // =============
    initial begin
        #(CLK_PERIOD * 10000000);
        $fatal(1, "Arithmetic timeout");
    end

    // =========
    // Main test
    // =========
    initial begin
        integer   fd;
        integer   n;
        integer   length;
        integer   scan_count;
        integer   watchdog;
        operand_t av;
        operand_t bv;
        string    path;
        if (!$value$plusargs("VECTORS=%s", path))
            $fatal(1, "Missing arithmetic vectors");
        fd = $fopen(path, "r");
        if (fd == 0)
            $fatal(1, "Cannot open arithmetic vectors");
        scan_count = $fscanf(fd, "%d", n);
        reset_dut();
        for (int test = 0; test < n; test++) begin
            scan_count = $fscanf(fd, "%d", length);
            if (scan_count != 1)
                $fatal(1, "Bad arithmetic length");
            for (int k = 0; k < length; k++) begin
                scan_count = $fscanf(fd, "%h %h", av, bv);
                if (scan_count != 2)
                    $fatal(1, "Bad arithmetic operand");
                @(negedge clk);
                a     = av;
                b     = bv;
                valid = 1;
                tag   = {k == 0, k == length - 1};
                ce    = ($urandom_range(0, 4) != 0);
                @(posedge clk);
                while (!ce) begin
                    @(negedge clk);
                    ce = ($urandom_range(0, 4) != 0);
                    @(posedge clk);
                end
            end
            scan_count = $fscanf(fd, "%h %h", expected, expected_flags);
            if (scan_count != 2)
                $fatal(1, "Bad arithmetic result");
            @(negedge clk);
            valid    = 0;
            ce       = 1;
            watchdog = 0;
            do begin
                @(posedge clk);
                watchdog++;
                if (watchdog > 1000)
                    $fatal(1, "Arithmetic result timeout");
            end while (!result_valid);
            check(test);
            @(negedge clk);
        end
        $fclose(fd);
        $display("Passed: %0d", pass_count);
        $display("Failed: %0d", fail_count);
        if (fail_count != 0 || pass_count == 0)
            $fatal(1, "ARITHMETIC FAILED");
        $display("ARITHMETIC PASSED");
        $finish;
    end
endmodule
